#include "tracker.hpp"
#include "CrackV4.h"
namespace {
cv::Mat1b view(const CrackV4Image*i){if(!i||!i->data||i->width<16||i->height<16||i->stride<i->width)throw std::runtime_error("invalid image");return cv::Mat1b(i->height,i->width,const_cast<unsigned char*>(i->data),size_t(i->stride));}
std::array<r05g::P,2> anchors(const CrackV4Point*p){if(!p)throw std::runtime_error("missing anchors");return {r05g::P(p[0].x,p[0].y),r05g::P(p[1].x,p[1].y)};}
bool configure(r05g::Tracker&d,int variant){d.cfg={};
#ifndef R05G_ENABLE_BEAM
 if(variant!=0)return false;
#endif
 switch(variant){case 0:d.cfg.beam=1;break;case 1:d.cfg.beam=4;d.cfg.history=true;break;case 2:d.cfg.beam=4;d.cfg.gap=false;d.cfg.history=true;break;case 3:d.cfg.beam=4;d.cfg.weak=false;d.cfg.history=true;break;case 4:d.cfg.beam=4;break;case 5:d.cfg.beam=1;d.cfg.maxScans=65536;d.cfg.maxNodes=400000;d.cfg.maxTotal=64000000;d.cfg.maxUnique=8000000;d.cfg.maxMs=0;break;case 6:d.cfg.beam=4;d.cfg.maxScans=65536;d.cfg.maxNodes=400000;d.cfg.maxTotal=64000000;d.cfg.maxUnique=8000000;d.cfg.maxMs=0;break;default:return false;}return true;}
std::string describe(r05g::Tracker&d){auto&r=d.r;std::ostringstream o;o<<std::setprecision(12);auto point=[&](r05g::P p){o<<'['<<p.x<<','<<p.y<<']';};auto observation=[&](const r05g::Observation&c){o<<"{\"xy\":";point(c.p);o<<",\"normal_offset\":"<<c.u<<",\"strength\":"<<c.strength<<",\"width_scale\":"<<c.width<<",\"quality\":"<<c.quality<<",\"intensity\":"<<c.intensity<<",\"asymmetry\":"<<c.asymmetry<<",\"weak\":"<<c.weak<<",\"band_border\":"<<c.border<<'}';};
 o<<"{\"frame\":"<<r.frame<<",\"mode\":\""<<(r.mode?"DIAGNOSTIC_SEEDED_ONLY":"AUTO_P1P2_HISTORY")<<"\",\"origin\":";point(r.origin);o<<",\"forward\":";point(r.forward);
 o<<",\"spacing\":"<<r.spacing<<",\"valid_geometry\":"<<r.valid<<",\"observed\":false,\"predicted\":false,\"state\":\"fallback\",\"tip\":null,\"trusted_history_written\":false,\"trusted_history_size\":"<<d.trustedHistory.size()<<",\"proposed_observed\":"<<r.proposedObserved<<",\"attribution_state\":\"IDENTITY_UNVERIFIED\",\"search_incomplete\":"<<r.incomplete<<",\"budget_reason\":\""<<(r.incomplete?r.reason:"")<<"\",\"reason\":\""<<r.reason<<"\",\"unique_pixels_sampled\":"<<r.uniquePixels<<",\"bilinear_sample_count\":"<<r.totalSamples<<",\"original_pixel_reads\":"<<r.sourceReads<<",\"scanline_count\":"<<r.scans.size()<<",\"seed_scanlines\":"<<r.seedScans<<",\"window_or_strip_count\":"<<r.scans.size()<<",\"beam_expansions\":"<<r.beamExpansions<<",\"beam_survivors\":"<<r.ends.size()<<",\"max_active_beam\":"<<r.maxActive<<",\"weak_observations\":"<<r.weakObservations<<",\"missing_steps\":"<<r.missingSteps<<",\"gap_reacquisitions\":"<<r.gapReacquisitions<<",\"branch_deletions\":"<<r.branchDeletions<<",\"merge_deletions\":"<<r.mergeDeletions<<",\"reference_attempts\":0,\"reference_valid\":0,\"reference_state\":\"NOT_IMPLEMENTED\",\"stop_audit_samples\":"<<r.stopAuditSamples<<",\"time_total_native_ms\":"<<r.totalMs<<",\"time_scan_ms\":"<<r.scanMs<<",\"time_beam_ms\":"<<r.beamMs<<",\"time_ref_ms\":0,\"time_terminal_ms\":"<<r.terminalMs<<",\"beam_width\":"<<d.cfg.beam<<",\"gap_enabled\":"<<d.cfg.gap<<",\"weak_enabled\":"<<d.cfg.weak<<",\"selected_end\":"<<r.selected<<",\"tracking_tip\":";
 if(r.selected>=0)point(r.ends[r.selected].tip);else o<<"null";
 o<<",\"seeds\":[";for(size_t i=0;i<r.seeds.size();++i){if(i)o<<',';auto&s=r.seeds[i];o<<"{\"xy\":";point(s.p);o<<",\"tangent\":";point(s.t);o<<",\"evidence\":"<<s.evidence<<",\"source\":"<<s.source<<",\"origin_identity_proposal\":"<<s.identityProposal<<'}';}o<<"],\"ends\":[";
 for(size_t i=0;i<r.ends.size();++i){if(i)o<<',';auto&e=r.ends[i];o<<"{\"node\":"<<e.node<<",\"tip_node\":"<<e.tipNode<<",\"xy\":";point(e.tip);o<<",\"progress\":"<<e.progress<<",\"visible_fraction\":"<<e.coverage<<",\"rank\":"<<e.rank<<",\"terminal_supported\":"<<e.terminal<<",\"terminal_ambiguous\":"<<e.ambiguous<<",\"origin_identity_proposal\":"<<e.identityProposal<<",\"backward_hits\":"<<e.backwardHits<<",\"forward_hits\":"<<e.forwardHits<<",\"reason\":\""<<e.reason<<"\"}";}o<<"],\"selected_path\":[";
 std::vector<int>path;if(r.selected>=0){int id=r.ends[r.selected].node;while(id>=0){path.push_back(id);id=r.nodes[id].parent;}std::reverse(path.begin(),path.end());}
 auto node=[&](const r05g::Node&n){o<<"{\"id\":"<<n.id<<",\"parent\":"<<n.parent<<",\"scan\":"<<n.scan<<",\"step\":"<<n.step<<",\"seed\":"<<n.seed<<",\"xy\":";point(n.p);o<<",\"tangent\":";point(n.t);o<<",\"visible\":"<<n.visible<<",\"strength\":"<<n.strength<<",\"width_scale\":"<<n.width<<",\"quality\":"<<n.quality<<",\"ema\":"<<n.ema<<",\"missing_distance\":"<<n.missing<<",\"max_missing\":"<<n.maxMissing<<",\"distance\":"<<n.distance<<",\"visible_distance\":"<<n.visibleDistance<<",\"reacquisitions\":"<<n.reacquisitions<<",\"pending_reacquisition\":"<<n.pending<<",\"retained\":"<<n.retained<<",\"decision\":\""<<n.decision<<"\"}";};
 for(size_t i=0;i<path.size();++i){if(i)o<<',';node(r.nodes[path[i]]);}o<<"],\"scans\":[";
 for(size_t i=0;i<r.scans.size();++i){if(i)o<<',';auto&s=r.scans[i];o<<"{\"id\":"<<s.id<<",\"parent\":"<<s.parent<<",\"step_index\":"<<s.step<<",\"predicted_point\":";point(s.predicted);o<<",\"tangent\":";point(s.tangent);o<<",\"normal\":";point(r05g::P(-s.tangent.y,s.tangent.x));o<<",\"halfwidth\":"<<s.half<<",\"max_radius\":"<<s.maxRadius<<",\"phase\":\""<<s.phase<<"\",\"sample_count\":"<<s.sampleCount<<",\"unique_after\":"<<s.uniqueAfter<<",\"processing_ms\":"<<s.time;
  o<<",\"window_polygon\":[";r05g::P normal(-s.tangent.y,s.tangent.x);double extent=std::ceil(s.half)+s.maxRadius+2;for(int k=0;k<4;++k){if(k)o<<',';point(s.predicted+s.tangent*((k<2?-.8:.8))+normal*((k==0||k==3?-extent:extent)));}o<<']';
  if(d.detail){o<<",\"raw_candidates\":[";for(size_t j=0;j<s.rawCandidates.size();++j){if(j)o<<',';observation(s.rawCandidates[j]);}o<<']';o<<",\"candidates\": [";for(size_t j=0;j<s.candidates.size();++j){if(j)o<<',';observation(s.candidates[j]);}o<<"],\"children\": [";for(size_t j=0;j<s.children.size();++j){if(j)o<<',';o<<s.children[j];}o<<']';}
  if(d.detail>=2){o<<",\"profile\": [";for(size_t j=0;j<s.profile.size();++j){if(j)o<<',';o<<s.profile[j];}o<<"],\"response\": [";for(size_t j=0;j<s.response.size();++j){if(j)o<<',';o<<s.response[j];}o<<']';}o<<'}';
 }o<<"],\"nodes\": [";if(d.detail)for(size_t i=0;i<r.nodes.size();++i){if(i)o<<',';node(r.nodes[i]);}o<<"]}";return o.str();}
}
extern "C" {
__declspec(dllexport) void* R05GCreate(const CrackV4Image*reference){try{auto im=view(reference);cv::setNumThreads(4);return new r05g::Tracker(im.size());}catch(...){return nullptr;}}
__declspec(dllexport) int R05GProcessAuto(void*h,const CrackV4Image*current,const CrackV4Point*pp,int variant,int detail){try{if(!h)return -1;auto&d=*static_cast<r05g::Tracker*>(h);if(!configure(d,variant))return -3;d.detail=detail;d.process(view(current),anchors(pp),nullptr);return 0;}catch(...){if(h){auto&d=*static_cast<r05g::Tracker*>(h);d.r={};d.r.valid=false;d.r.incomplete=true;d.r.reason="invalid_api_input";}return -2;}}
__declspec(dllexport) int R05GProcessDiagnostic(void*h,const CrackV4Image*current,const CrackV4Point*pp,const double*seed,int count,int variant,int detail){try{if(!h||!seed||count<1||count>3)return -1;auto&d=*static_cast<r05g::Tracker*>(h);if(!configure(d,variant))return -3;std::vector<r05g::Seed>seeds;for(int i=0;i<count;++i){r05g::Seed s;s.p={seed[4*i],seed[4*i+1]};s.t={seed[4*i+2],seed[4*i+3]};s.source=1;s.evidence=1;seeds.push_back(s);}d.detail=detail;d.process(view(current),anchors(pp),&seeds);return 0;}catch(...){if(h){auto&d=*static_cast<r05g::Tracker*>(h);d.r={};d.r.valid=false;d.r.incomplete=true;d.r.reason="invalid_api_input";}return -2;}}
__declspec(dllexport) const char* R05GRead(void*h){if(!h)return "{}";auto&d=*static_cast<r05g::Tracker*>(h);d.json=describe(d);return d.json.c_str();}
__declspec(dllexport) void R05GDestroy(void*h){delete static_cast<r05g::Tracker*>(h);}
}
